"""Stateless, causal core-temperature predictions (degrees Celsius).

The 15-minute model blends a person-balanced training-set time curve with an
ECTemp-style filtered sensor signal.  It is an empirical comparator, not a
validated medical device or a reproduction of the published ECTemp model.
"""

import math


def _number(row, name):
    value = row.get(name)
    if value is None:
        return None
    try:
        value = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return value if math.isfinite(value) else None


def _clamp(x, low, high):
    return max(low, min(high, x))


def predict(request):
    rows = request.get('history') or []
    if not rows:
        return {'mean': 37.5, 'lower': 36.5, 'upper': 38.5}

    # Work with elapsed time only: independent clock offsets must not matter.
    t0 = _number(rows[0], 'time_min')
    if t0 is None:
        t0 = 0.0
    end = _number(rows[-1], 'time_min')
    if end is None:
        end = t0 + len(rows) - 1
    elapsed = _clamp(end - t0 + 1.0, 0.0, 120.0)

    # One-pole physiological comparator. Before the first HR value, use the
    # template's 80-bpm convention for the first five rows; for later missing
    # data use a reasonable exercise fallback, or carry the last observation.
    state = 37.0
    speed = 0.0
    previous_time = None
    last_hr = last_skin = last_watts = None
    latest_mass = None
    recent_watts = []
    recent_hr_count = recent_skin_count = recent_watts_count = 0
    for i, row in enumerate(rows):
        now = _number(row, 'time_min')
        if previous_time is None or now is None:
            dt = 1.0
        else:
            dt = _clamp(now - previous_time, 0.0, 30.0)
        if now is not None:
            previous_time = now
        elif previous_time is not None:
            previous_time += dt

        hr = _number(row, 'hr')
        skin = _number(row, 'skin_temp')
        watts = _number(row, 'watts')
        mass = _number(row, 'mass')
        if mass is not None:
            latest_mass = mass
        if hr is not None:
            last_hr = _clamp(hr, 35.0, 230.0)
        if skin is not None:
            last_skin = _clamp(skin, 25.0, 45.0)
        if watts is not None:
            last_watts = _clamp(watts, 0.0, 500.0)
        if i >= len(rows) - 5:
            if hr is not None:
                recent_hr_count += 1
            if skin is not None:
                recent_skin_count += 1
            if watts is not None:
                recent_watts_count += 1
                recent_watts.append(_clamp(watts, 0.0, 500.0))

        hr_val = last_hr if last_hr is not None else (80.0 if i < 5 else 150.0)
        skin_val = last_skin if last_skin is not None else 34.0
        watts_val = last_watts if last_watts is not None else 165.0
        target = (36.7 + 0.012 * (hr_val - 70.0)
                  + 0.045 * (skin_val - 33.0) + 0.001 * watts_val)
        gain = 0.08 if dt == 1.0 else 1.0 - (1.0 - 0.08) ** dt
        previous_state = state
        state += gain * (target - state)
        speed = (state - previous_state) / dt if dt > 0 else 0.0

    is_current = request.get('task') == '3B'
    if is_current:
        x = min(elapsed, 60.0) / 30.0
        curve = 37.2639307349 + 1.4570267886*x - 0.3490469450*x*x
        mean = 0.75*curve + 0.25*(state + 0.4)
    else:
        # The time curve is fitted to future +15-minute labels, not current
        # core temperature. The filtered sensor forecast is a bounded trend.
        x = min(elapsed, 50.0) / 30.0
        curve = 37.9202308599 + 1.1001480725*x - 0.3549011575*x*x
        sensor_forecast = state + 15.0*_clamp(speed, -0.03, 0.03)
        mean = 0.5*curve + 0.5*(sensor_forecast + 0.5)
        # Modest, saturating correction for unusually low mass-specific work.
        mass = _clamp(latest_mass, 40.0, 140.0) if latest_mass is not None else 75.0
        watts = (sum(recent_watts)/len(recent_watts) if recent_watts
                 else (last_watts if last_watts is not None else 165.0))
        wkg = watts / mass
        mean -= 0.2 * _clamp((1.8 - wkg)/0.5, 0.0, 1.0)

    # Empirical 90% interval; widen when recent sensor information is absent.
    half_width = 0.7
    if elapsed > 6 and recent_hr_count == 0:
        half_width += 0.15
    if recent_skin_count == 0:
        half_width += 0.10
    if recent_watts_count == 0:
        half_width += 0.10
    if latest_mass is None and not is_current:
        half_width += 0.05
    return {'mean': float(mean), 'lower': float(mean-half_width),
            'upper': float(mean+half_width)}
